    /**
     * Boton que se encarga de llamar un método para validar que el campo sea correcto y encontrar la raíz cuadradra del valor
     * @param evt Dar click
     */
    private void btnRaizcuadradaActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnRaizcuadradaActionPerformed
        if(txtValor1.getText().trim().length() <= 0){
            JOptionPane.showMessageDialog(null, "Favor ingresar valor 1, porque el campo esta vacio.");
            txtValor1.requestFocus();
        } else if(txtValor2.getText().trim().length() > 0){
            JOptionPane.showMessageDialog(null, "Favor dejar el valor 2 despejado, porque el campo necesario solamente es el primero para esta operación.");
            txtValor2.requestFocus();
            return;
        }
        raizCuadradaValores();
    }//GEN-LAST:event_btnRaizcuadradaActionPerformed

