    /**
     * Asegura que los campos no estén vacíos
     */
    private void validarCampos(){
        if(txtValor1.getText().trim().length() <= 0){
            JOptionPane.showMessageDialog(null, "Favor ingresar valor 1, porque el campo esta vacio.");
            txtValor1.requestFocus();
        } else if(txtValor2.getText().trim().length() <= 0){
            JOptionPane.showMessageDialog(null, "Favor ingresar valor 2, porque el campo esta vacio.");
            txtValor2.requestFocus();
        }
    }
    
    /**
     * Gestiona la suma de los valores ingresados
     */
    private void sumarValores(){
        Calculadora cal = new Calculadora();
        Double respuesta = cal.sumar(Double.parseDouble(txtValor1.getText()), Double.parseDouble(txtValor2.getText()));
        txtRespuesta.setText(respuesta +"");
    }
    
    /**
     * Gestiona la resta de los valores ingresados
     */
    private void restarValores(){
        Calculadora cal = new Calculadora();
        Double respuesta = cal.restar(Double.parseDouble(txtValor1.getText()), Double.parseDouble(txtValor2.getText()));
        txtRespuesta.setText(respuesta +"");
    }
    
    /**
     * Gestiona la multiplicación de los valores ingresados
     */
    private void multiplicarValores(){
        Calculadora cal = new Calculadora();
        Double respuesta = cal.multiplicar(Double.parseDouble(txtValor1.getText()), Double.parseDouble(txtValor2.getText()));
        txtRespuesta.setText(respuesta +"");
    }
    
    /**
     * Gestiona la división de los valores ingresados
     */
    private void dividirValores(){
        Calculadora cal = new Calculadora();
        if(Double.parseDouble(txtValor2.getText()) == 0){
            JOptionPane.showMessageDialog(null, "No es posible dividir un número por cero");
            txtValor2.requestFocus();
            return;
        }
        Double respuesta = cal.dividir(Double.parseDouble(txtValor1.getText()), Double.parseDouble(txtValor2.getText()));
        txtRespuesta.setText(respuesta +"");
    }
    
    /**
     * Gestiona la raíz cuadrada del valor ingresado
     */
    private void raizCuadradaValores(){
        Raizcuadrada_Exponente cal = new Raizcuadrada_Exponente();
        
        Double respuesta = cal.raizcuadrada(Double.parseDouble(txtValor1.getText()));
        txtRespuesta.setText(respuesta +"");
    }
    
    /**
     * Gestiona la potenciación del valore ingresado
     */
    private void exponenciarValores(){
        Raizcuadrada_Exponente cal = new Raizcuadrada_Exponente();
        Double respuesta = cal.exponenciar(Double.parseDouble(txtValor1.getText()), Double.parseDouble(txtValor2.getText()));
        txtRespuesta.setText(respuesta +"");
    }
    
    /**
     * Matiene los campos vacíos
     */
    private void limpiarCampos(){
        txtValor1.setText("");
        txtValor2.setText("");
        txtRespuesta.setText("");
        txtValor1.requestFocus();
    }
    
